    from collections import Counter, deque
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    ink = next(v for row in grid for v in row if v != bg)
    # Label 4-connected components of the original marked cells.
    comp = [[-1] * w for _ in range(h)]
    label = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != ink or comp[r][c] >= 0:
                continue
            comp[r][c] = label
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
